+/* =========================================
+   Base & Reset
+   ========================================= */
+*, *::before, *::after {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+:root {
+  --color-brand:       #1a1a2e;
+  --color-accent:      #e94560;
+  --color-accent-dark: #c73652;
+  --color-bg:          #f8f8f6;
+  --color-surface:     #ffffff;
