+  --color-text-muted:  #6b6b80;
+  --color-badge-deal:  #ff6b35;
+  --color-badge-new:   #2ec4b6;
+
+  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
+  --font-serif: 'Georgia', 'Times New Roman', serif;
+
+  --radius-sm:  4px;
+  --radius-md:  8px;
+  --radius-lg:  16px;
+  --radius-xl:  24px;
+
+  --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
+  --shadow-md: 0 4px 16px rgba(0,0,0,.10);
+  --shadow-lg: 0 8px 32px rgba(0,0,0,.12);
+
+  --max-width: 1280px;
+  --header-height: 64px;
+
+  --transition: 200ms ease;
+}
+
+html {
+  scroll-behavior: smooth;
+}
+
+body {
+  font-family: var(--font-sans);
+  background: var(--color-bg);
+  color: var(--color-text);
+  line-height: 1.6;
+  -webkit-font-smoothing: antialiased;
+}
+
+img {
+  display: block;
+  max-width: 100%;
+}
+
+a {
+  color: inherit;
+  text-decoration: none;
+}
+
+ul, ol {
+  list-style: none;
+}
+
+button {
+  cursor: pointer;
+  border: none;
+  background: none;
+  font-family: inherit;
+}
+
+/* =========================================
+   Skip Link (Accessibility)
+   ========================================= */
+.skip-link {
+  position: absolute;
+  top: -100%;
+  left: 1rem;
+  padding: .5rem 1rem;
+  background: var(--color-accent);
+  color: #fff;
+  font-weight: 600;
+  border-radius: var(--radius-md);
+  z-index: 9999;
+  transition: top var(--transition);
+}
+.skip-link:focus {
+  top: 1rem;
+}
+
+/* =========================================
+   Layout Utilities
+   ========================================= */
+.container {
+  width: 100%;
+  max-width: var(--max-width);
+  margin-inline: auto;
+  padding-inline: 1.5rem;
+}
+
+.section-header {
+  display: flex;
+  align-items: baseline;
+  justify-content: space-between;
+  margin-bottom: 2rem;
+  gap: 1rem;
+}
+
+.section-title {
+  font-size: clamp(1.25rem, 2vw, 1.75rem);
+  font-weight: 700;
+  letter-spacing: -.02em;
+}
+
+.section-link {
+  font-size: .875rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  white-space: nowrap;
+  display: inline-flex;
+  align-items: center;
+  gap: .25rem;
+  transition: gap var(--transition);
+}
+.section-link:hover,
+.section-link:focus-visible {
+  gap: .5rem;
+}
+.section-link:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 3px;
+  border-radius: var(--radius-sm);
+}
+
+/* =========================================
+   Announcement Banner
+   ========================================= */
+.announcement-bar {
+  background: var(--color-brand);
+  color: #fff;
+  text-align: center;
+  padding: .5rem 1rem;
+  font-size: .8125rem;
+  font-weight: 500;
+  letter-spacing: .02em;
+}
+.announcement-bar strong { color: var(--color-accent); }
+
+/* =========================================
+   Header & Navigation
+   ========================================= */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 100;
+  background: var(--color-surface);
+  border-bottom: 1px solid var(--color-border);
+  box-shadow: var(--shadow-sm);
+}
+
+.header-inner {
+  height: var(--header-height);
+  display: grid;
+  grid-template-columns: 1fr auto 1fr;
+  align-items: center;
+  gap: 1rem;
+}
+
+/* Logo */
+.site-logo {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  font-size: 1.25rem;
+  font-weight: 800;
+  letter-spacing: -.04em;
+  color: var(--color-brand);
+  justify-self: start;
+}
+.site-logo:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 3px;
+  border-radius: var(--radius-sm);
+}
+.logo-mark {
+  width: 32px;
+  height: 32px;
+  background: var(--color-accent);
+  border-radius: var(--radius-sm);
+  display: grid;
+  place-items: center;
+  color: #fff;
+  font-size: .875rem;
+}
+
+/* Primary Nav */
+.primary-nav {
+  display: flex;
+  align-items: center;
+  gap: .25rem;
+}
+.nav-link {
+  padding: .375rem .75rem;
+  font-size: .9375rem;
+  font-weight: 500;
+  border-radius: var(--radius-sm);
+  transition: background var(--transition), color var(--transition);
+  color: var(--color-text-muted);
+}
+.nav-link:hover,
+.nav-link:focus-visible {
+  background: var(--color-bg);
+  color: var(--color-text);
+}
+.nav-link:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+.nav-link[aria-current="page"] {
+  color: var(--color-text);
+  font-weight: 600;
+}
+
+/* Header Actions */
+.header-actions {
+  display: flex;
+  align-items: center;
+  gap: .25rem;
+  justify-self: end;
+}
+.icon-btn {
+  width: 40px;
+  height: 40px;
+  border-radius: var(--radius-md);
+  display: grid;
+  place-items: center;
+  color: var(--color-text-muted);
+  transition: background var(--transition), color var(--transition);
+  position: relative;
+}
+.icon-btn:hover,
+.icon-btn:focus-visible {
+  background: var(--color-bg);
+  color: var(--color-text);
+}
+.icon-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+.cart-count {
+  position: absolute;
+  top: 4px;
+  right: 4px;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: .625rem;
+  font-weight: 700;
+  min-width: 16px;
+  height: 16px;
+  border-radius: 100px;
+  display: grid;
+  place-items: center;
+  padding-inline: 3px;
+  line-height: 1;
+}
+
+/* Mobile menu toggle */
+.menu-toggle {
+  display: none;
+  width: 40px;
+  height: 40px;
+  border-radius: var(--radius-md);
+  align-items: center;
+  justify-content: center;
+  color: var(--color-text);
+}
+.menu-toggle:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+/* =========================================
+   Search Bar (inline)
+   ========================================= */
+.search-form {
+  display: flex;
+  align-items: center;
+  background: var(--color-bg);
+  border: 1.5px solid var(--color-border);
+  border-radius: 100px;
+  padding: .25rem .25rem .25rem .875rem;
+  gap: .5rem;
+  transition: border-color var(--transition), box-shadow var(--transition);
+  width: 280px;
+  max-width: 100%;
+}
+.search-form:focus-within {
+  border-color: var(--color-accent);
+  box-shadow: 0 0 0 3px rgba(233,69,96,.15);
+}
+.search-input {
+  flex: 1;
+  border: none;
+  background: transparent;
+  font-size: .875rem;
+  color: var(--color-text);
+  font-family: inherit;
+  min-width: 0;
+}
+.search-input::placeholder { color: var(--color-text-muted); }
+.search-input:focus { outline: none; }
+.search-btn {
+  width: 30px;
+  height: 30px;
+  background: var(--color-accent);
+  color: #fff;
+  border-radius: 100px;
+  display: grid;
+  place-items: center;
+  flex-shrink: 0;
+  transition: background var(--transition);
+}
+.search-btn:hover { background: var(--color-accent-dark); }
+.search-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 3px;
+}
+
+/* =========================================
+   Hero Section
+   ========================================= */
+.hero {
+  background: var(--color-brand);
+  color: #fff;
+  overflow: hidden;
+  position: relative;
+}
+
+.hero-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  min-height: 540px;
+  align-items: center;
+  gap: 3rem;
+  padding-block: 4rem;
+}
+
+.hero-eyebrow {
+  display: inline-flex;
+  align-items: center;
+  gap: .5rem;
+  background: rgba(233,69,96,.18);
+  border: 1px solid rgba(233,69,96,.4);
+  color: #f9a0b0;
+  font-size: .8125rem;
+  font-weight: 600;
+  letter-spacing: .06em;
+  text-transform: uppercase;
+  padding: .25rem .75rem;
+  border-radius: 100px;
+  margin-bottom: 1.25rem;
+}
+
+.hero-title {
+  font-size: clamp(2rem, 5vw, 3.5rem);
+  font-weight: 800;
+  line-height: 1.1;
+  letter-spacing: -.03em;
+  margin-bottom: 1.25rem;
+}
+.hero-title em {
+  font-style: normal;
+  color: var(--color-accent);
+}
+
+.hero-description {
+  font-size: 1.0625rem;
+  color: rgba(255,255,255,.72);
+  max-width: 42ch;
+  margin-bottom: 2rem;
+  line-height: 1.7;
+}
+
+.hero-actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: .75rem;
+}
+
+.hero-visual {
+  position: relative;
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 1rem;
+  align-items: start;
+}
+
+.hero-card {
+  background: rgba(255,255,255,.07);
+  border: 1px solid rgba(255,255,255,.12);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  transition: transform var(--transition);
+}
+.hero-card:hover { transform: translateY(-4px); }
+.hero-card:first-child { margin-top: 2rem; }
+
+.hero-card-img {
+  width: 100%;
+  aspect-ratio: 3/4;
+  object-fit: cover;
+  background: linear-gradient(135deg, #2d2d44, #4a1942);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 4rem;
+}
+
+.hero-card-body {
+  padding: .875rem;
+}
+.hero-card-name {
+  font-size: .875rem;
+  font-weight: 600;
+  margin-bottom: .25rem;
+  color: rgba(255,255,255,.92);
+}
+.hero-card-price {
+  font-size: .8125rem;
+  color: var(--color-accent);
+  font-weight: 700;
+}
+
+/* =========================================
+   Buttons
+   ========================================= */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: .5rem;
+  padding: .75rem 1.5rem;
+  font-size: .9375rem;
+  font-weight: 600;
+  border-radius: var(--radius-md);
+  transition: background var(--transition), color var(--transition), transform var(--transition), box-shadow var(--transition);
+  font-family: inherit;
+  line-height: 1;
+}
+.btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 3px;
+}
+
+.btn-primary {
+  background: var(--color-accent);
+  color: #fff;
+}
+.btn-primary:hover {
+  background: var(--color-accent-dark);
+  transform: translateY(-1px);
+  box-shadow: 0 4px 12px rgba(233,69,96,.4);
+}
+
+.btn-secondary {
+  background: rgba(255,255,255,.1);
+  color: #fff;
+  border: 1.5px solid rgba(255,255,255,.25);
+}
+.btn-secondary:hover {
+  background: rgba(255,255,255,.2);
+}
+
+.btn-outline {
+  background: transparent;
+  color: var(--color-text);
+  border: 1.5px solid var(--color-border);
+}
+.btn-outline:hover {
+  border-color: var(--color-text);
+  background: var(--color-text);
+  color: #fff;
+}
+
+.btn-sm {
+  padding: .5rem 1rem;
+  font-size: .8125rem;
+  border-radius: var(--radius-sm);
+}
+
+.btn-icon {
+  width: 40px;
+  height: 40px;
+  padding: 0;
+  border-radius: var(--radius-md);
+  display: grid;
+  place-items: center;
+}
+
+/* =========================================
+   Category Chips
+   ========================================= */
+.categories {
+  padding-block: 2rem;
+  border-bottom: 1px solid var(--color-border);
+}
+
+.category-list {
+  display: flex;
+  gap: .75rem;
+  overflow-x: auto;
+  scrollbar-width: none;
+  padding-bottom: .5rem;
+  -webkit-overflow-scrolling: touch;
+}
+.category-list::-webkit-scrollbar { display: none; }
+
+.category-chip {
+  flex-shrink: 0;
+  display: inline-flex;
+  flex-direction: column;
+  align-items: center;
+  gap: .5rem;
+  padding: .875rem 1.25rem;
+  background: var(--color-surface);
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  font-size: .8125rem;
+  font-weight: 600;
+  color: var(--color-text-muted);
+  cursor: pointer;
+  transition: border-color var(--transition), color var(--transition), background var(--transition);
+  text-decoration: none;
+}
+.category-chip:hover,
+.category-chip:focus-visible {
+  border-color: var(--color-accent);
+  color: var(--color-accent);
+  background: rgba(233,69,96,.05);
+}
+.category-chip:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+.category-chip[aria-pressed="true"] {
+  border-color: var(--color-accent);
+  color: var(--color-accent);
+  background: rgba(233,69,96,.08);
+}
+.category-icon {
+  font-size: 1.5rem;
+  line-height: 1;
+}
+
+/* =========================================
+   Product Cards
+   ========================================= */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
+  gap: 1.5rem;
+}
+
+.product-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  transition: box-shadow var(--transition), transform var(--transition);
+  display: flex;
+  flex-direction: column;
+}
+.product-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-2px);
+}
+
+.product-card-media {
+  position: relative;
+  aspect-ratio: 1;
+  background: var(--color-bg);
+  overflow: hidden;
+}
+
+.product-img {
+  width: 100%;
+  height: 100%;
+  object-fit: cover;
+  transition: transform 400ms ease;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 5rem;
+}
+.product-card:hover .product-img {
+  transform: scale(1.04);
+}
+
+.product-badges {
+  position: absolute;
+  top: .75rem;
+  left: .75rem;
+  display: flex;
+  flex-direction: column;
+  gap: .375rem;
+}
+.badge {
+  display: inline-block;
+  padding: .2rem .5rem;
+  border-radius: 100px;
+  font-size: .6875rem;
+  font-weight: 700;
+  letter-spacing: .03em;
+  text-transform: uppercase;
+  line-height: 1.4;
+}
+.badge-new    { background: var(--color-badge-new);  color: #fff; }
+.badge-sale   { background: var(--color-accent);     color: #fff; }
+.badge-hot    { background: var(--color-badge-deal); color: #fff; }
+
+.product-actions {
+  position: absolute;
+  bottom: .75rem;
+  right: .75rem;
+  display: flex;
+  flex-direction: column;
+  gap: .375rem;
+  opacity: 0;
+  transform: translateX(8px);
+  transition: opacity var(--transition), transform var(--transition);
+}
+.product-card:hover .product-actions,
+.product-card:focus-within .product-actions {
+  opacity: 1;
+  transform: translateX(0);
+}
+.action-btn {
+  width: 36px;
+  height: 36px;
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-md);
+  display: grid;
+  place-items: center;
+  color: var(--color-text-muted);
+  font-size: .875rem;
+  transition: background var(--transition), color var(--transition), border-color var(--transition);
+}
+.action-btn:hover,
+.action-btn:focus-visible {
+  background: var(--color-accent);
+  color: #fff;
+  border-color: var(--color-accent);
+}
+.action-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+.product-card-body {
+  padding: 1rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+}
+.product-brand {
+  font-size: .75rem;
+  font-weight: 600;
+  color: var(--color-text-muted);
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  margin-bottom: .25rem;
+}
+.product-name {
+  font-size: .9375rem;
+  font-weight: 600;
+  line-height: 1.3;
+  margin-bottom: .5rem;
+  color: var(--color-text);
+}
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: .375rem;
+  margin-bottom: .625rem;
+}
+.stars {
+  display: flex;
+  gap: 1px;
+  color: #f59e0b;
+  font-size: .8125rem;
+}
+.rating-count {
+  font-size: .75rem;
+  color: var(--color-text-muted);
+}
+.product-pricing {
+  display: flex;
+  align-items: center;
+  gap: .625rem;
+  margin-top: auto;
+  flex-wrap: wrap;
+}
+.price-current {
+  font-size: 1.0625rem;
+  font-weight: 700;
+  color: var(--color-text);
+}
+.price-original {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+.price-discount {
+  font-size: .75rem;
+  font-weight: 700;
+  color: var(--color-accent);
+}
+
+.product-card-footer {
+  padding: .75rem 1rem 1rem;
+  border-top: 1px solid var(--color-border);
+}
+
+.add-to-cart-btn {
+  width: 100%;
+  background: var(--color-brand);
+  color: #fff;
+  padding: .625rem;
+  border-radius: var(--radius-md);
+  font-size: .875rem;
+  font-weight: 600;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  gap: .5rem;
+  transition: background var(--transition), transform var(--transition);
+}
+.add-to-cart-btn:hover {
+  background: var(--color-accent);
+  transform: translateY(-1px);
+}
+.add-to-cart-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 3px;
+}
+
+/* =========================================
+   Sections Spacing
+   ========================================= */
+.section {
+  padding-block: 4rem;
+}
+.section + .section {
+  border-top: 1px solid var(--color-border);
+}
+
+/* =========================================
+   Deals Section
+   ========================================= */
+.deals-section {
+  background: linear-gradient(135deg, #fff5f7 0%, #fff8f0 100%);
+}
+
+.countdown-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 1.5rem;
+}
+
+/* Featured Deal Card (large) */
+.deal-featured {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-xl);
+  overflow: hidden;
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  box-shadow: var(--shadow-md);
+}
+
+.deal-featured-media {
+  background: linear-gradient(135deg, #1a1a2e, #3a1a3a);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 8rem;
+  min-height: 320px;
+}
+
+.deal-featured-body {
+  padding: 2.5rem 2rem;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  gap: 1rem;
+}
+
+.deal-tag {
+  display: inline-flex;
+  align-items: center;
+  gap: .375rem;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: .75rem;
+  font-weight: 700;
+  padding: .3rem .75rem;
+  border-radius: 100px;
+  text-transform: uppercase;
+  letter-spacing: .05em;
+  align-self: flex-start;
+}
+
+.deal-title {
+  font-size: 1.5rem;
+  font-weight: 800;
+  letter-spacing: -.02em;
+  line-height: 1.2;
+}
+
+.deal-description {
+  font-size: .9375rem;
+  color: var(--color-text-muted);
+  line-height: 1.6;
+}
+
+.deal-pricing {
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+}
+.deal-price-current {
+  font-size: 2rem;
+  font-weight: 800;
+  color: var(--color-accent);
+}
+.deal-price-original {
+  font-size: 1rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+.deal-discount-badge {
+  background: rgba(233,69,96,.1);
+  color: var(--color-accent);
+  font-size: .8125rem;
+  font-weight: 700;
+  padding: .25rem .625rem;
+  border-radius: 100px;
+}
+
+.countdown {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+}
+.countdown-label {
+  font-size: .8125rem;
+  color: var(--color-text-muted);
+  font-weight: 500;
+}
+.countdown-timer {
+  display: flex;
+  align-items: center;
+  gap: .25rem;
+}
+.countdown-segment {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  background: var(--color-brand);
+  color: #fff;
+  border-radius: var(--radius-sm);
+  padding: .25rem .5rem;
+  min-width: 38px;
+}
+.countdown-num {
+  font-size: 1.125rem;
+  font-weight: 800;
+  line-height: 1;
+  font-variant-numeric: tabular-nums;
+}
+.countdown-unit {
+  font-size: .5625rem;
+  font-weight: 600;
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  color: rgba(255,255,255,.6);
+}
+.countdown-sep {
+  font-size: 1.125rem;
+  font-weight: 700;
+  color: var(--color-text-muted);
+  margin-bottom: .5rem;
+}
+
+/* Mini Deal Cards */
+.deals-sidebar {
+  display: flex;
+  flex-direction: column;
+  gap: 1.5rem;
+}
+
+.deal-mini-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  padding: 1.25rem;
+  display: grid;
+  grid-template-columns: 80px 1fr;
+  gap: 1rem;
+  align-items: center;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.deal-mini-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-2px);
+}
+
+.deal-mini-media {
+  width: 80px;
+  height: 80px;
+  border-radius: var(--radius-md);
+  background: var(--color-bg);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 2.5rem;
+  flex-shrink: 0;
+  overflow: hidden;
+}
+
+.deal-mini-name {
+  font-size: .9375rem;
+  font-weight: 600;
+  margin-bottom: .375rem;
+  line-height: 1.3;
+}
+.deal-mini-pricing {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  margin-bottom: .5rem;
+}
+.deal-mini-price {
+  font-size: 1rem;
+  font-weight: 700;
+  color: var(--color-accent);
+}
+.deal-mini-original {
+  font-size: .8125rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+
+.deal-progress {
+  display: flex;
+  flex-direction: column;
+  gap: .25rem;
+}
+.progress-bar {
+  height: 5px;
+  background: var(--color-border);
+  border-radius: 100px;
+  overflow: hidden;
+}
+.progress-fill {
+  height: 100%;
+  background: linear-gradient(90deg, var(--color-accent), var(--color-badge-deal));
+  border-radius: 100px;
+  transition: width 1s ease;
+}
+.progress-label {
+  font-size: .6875rem;
+  color: var(--color-text-muted);
+}
+.progress-label strong { color: var(--color-accent); }
+
+/* =========================================
+   Trust Bar
+   ========================================= */
+.trust-bar {
+  background: var(--color-surface);
+  padding-block: 1.5rem;
+  border-top: 1px solid var(--color-border);
+  border-bottom: 1px solid var(--color-border);
+}
+
+.trust-list {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 1rem;
+  text-align: center;
+}
+
+.trust-item {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: .5rem;
+}
+.trust-icon {
+  font-size: 1.75rem;
+  line-height: 1;
+}
+.trust-title {
+  font-size: .875rem;
+  font-weight: 700;
+}
+.trust-subtitle {
+  font-size: .75rem;
+  color: var(--color-text-muted);
+}
+
+/* =========================================
+   Editorial / Content Section
+   ========================================= */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr 1fr;
+  gap: 1.5rem;
+}
+
+.editorial-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.editorial-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-2px);
+}
+
+.editorial-card--featured {
+  grid-column: span 2;
+}
+
+.editorial-media {
+  position: relative;
+  aspect-ratio: 16/9;
+  background: linear-gradient(135deg, #1a1a2e, #3a1a3a);
+  overflow: hidden;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+.editorial-card--featured .editorial-media {
+  aspect-ratio: 16/9;
+}
+
+.editorial-cover-emoji {
+  font-size: 6rem;
+  line-height: 1;
+  opacity: .9;
+}
+
+.editorial-media-overlay {
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(to top, rgba(0,0,0,.6) 0%, transparent 60%);
+}
+
+.editorial-category {
+  display: inline-flex;
+  align-items: center;
+  gap: .375rem;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: .6875rem;
+  font-weight: 700;
+  padding: .25rem .625rem;
+  border-radius: 100px;
+  text-transform: uppercase;
+  letter-spacing: .05em;
+  margin-bottom: .75rem;
+}
+
+.editorial-body {
+  padding: 1.25rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+  gap: .5rem;
+}
+
+.editorial-title {
+  font-size: 1.0625rem;
+  font-weight: 700;
+  line-height: 1.3;
+  letter-spacing: -.01em;
+}
+.editorial-card--featured .editorial-title {
+  font-size: 1.25rem;
+}
+
+.editorial-excerpt {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  line-height: 1.6;
+  flex: 1;
+}
+
+.editorial-meta {
+  display: flex;
+  align-items: center;
+  gap: .75rem;
+  font-size: .75rem;
+  color: var(--color-text-muted);
+  margin-top: .75rem;
+  padding-top: .75rem;
+  border-top: 1px solid var(--color-border);
+}
+.editorial-avatar {
+  width: 28px;
+  height: 28px;
+  border-radius: 50%;
+  background: var(--color-bg);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: .875rem;
+  flex-shrink: 0;
+  border: 1.5px solid var(--color-border);
+}
+.editorial-author { font-weight: 600; color: var(--color-text); }
+.editorial-read-more {
+  margin-left: auto;
+  display: inline-flex;
+  align-items: center;
+  gap: .25rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  font-size: .75rem;
+  transition: gap var(--transition);
+}
+.editorial-read-more:hover,
+.editorial-read-more:focus-visible { gap: .5rem; }
+.editorial-read-more:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+  border-radius: var(--radius-sm);
+}
