   Base & Reset
   ========================================= */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-brand:       #1a1a2e;
  --color-accent:      #e94560;
  --color-accent-dark: #c73652;
  --color-bg:          #f8f8f6;
  --color-surface:     #ffffff;
  --color-border:      #e2e2e2;
  --color-text:        #1a1a2e;
  --color-text-muted:  #6b6b80;
  --color-badge-deal:  #ff6b35;
  --color-badge-new:   #2ec4b6;

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-serif: 'Georgia', 'Times New Roman', serif;

  --radius-sm:  4px;
  --radius-md:  8px;
  --radius-lg:  16px;
  --radius-xl:  24px;

  --shadow-sm: 0 1px 3px rgba(0,0,0,.08);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10);
  --shadow-lg: 0 8px 32px rgba(0,0,0,.12);

  --max-width: 1280px;
  --header-height: 64px;

  --transition: 200ms ease;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

/* =========================================
   Skip Link (Accessibility)
   ========================================= */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  font-weight: 600;
  border-radius: var(--radius-md);
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

/* =========================================
   Layout Utilities
   ========================================= */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: 1.5rem;
}

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 2rem;
  gap: 1rem;
}

.section-title {
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -.02em;
}

.section-link {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-accent);
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  transition: gap var(--transition);
}
.section-link:hover,
.section-link:focus-visible {
  gap: .5rem;
}
.section-link:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* =========================================
   Announcement Banner
   ========================================= */
.announcement-bar {
  background: var(--color-brand);
  color: #fff;
  text-align: center;
  padding: .5rem 1rem;
  font-size: .8125rem;
  font-weight: 500;
  letter-spacing: .02em;
}
.announcement-bar strong { color: var(--color-accent); }

/* =========================================
   Header & Navigation
   ========================================= */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.header-inner {
  height: var(--header-height);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 1rem;
}

