.qty-btn:hover { background: var(--color-border); }
.qty-btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
.qty-val {
  font-size: .875rem;
  font-weight: 600;
  min-width: 1.5rem;
  text-align: center;
}
.cart-item-price {
  font-size: .9375rem;
  font-weight: 700;
  white-space: nowrap;
}
.cart-item-remove {
  display: block;
  color: var(--color-text-muted);
  font-size: .6875rem;
  font-weight: 600;
  margin-top: .375rem;
  transition: color var(--transition);
  cursor: pointer;
  background: none;
  border: none;
  font-family: inherit;
  padding: 0;
  text-align: right;
}
.cart-item-remove:hover { color: var(--color-accent); }
.cart-item-remove:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: var(--radius-sm);
}

