+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 5rem;
+}
+.product-card:hover .product-img {
+  transform: scale(1.04);
+}
+
+.product-badges {
+  position: absolute;
+  top: .75rem;
+  left: .75rem;
+  display: flex;
+  flex-direction: column;
+  gap: .375rem;
+}
+.badge {
+  display: inline-block;
+  padding: .2rem .5rem;
+  border-radius: 100px;
+  font-size: .6875rem;
+  font-weight: 700;
+  letter-spacing: .03em;
+  text-transform: uppercase;
+  line-height: 1.4;
+}
+.badge-new    { background: var(--color-badge-new);  color: #fff; }
+.badge-sale   { background: var(--color-accent);     color: #fff; }
+.badge-hot    { background: var(--color-badge-deal); color: #fff; }
+
+.product-actions {
+  position: absolute;
+  bottom: .75rem;
+  right: .75rem;
+  display: flex;
+  flex-direction: column;
+  gap: .375rem;
+  opacity: 0;
+  transform: translateX(8px);
+  transition: opacity var(--transition), transform var(--transition);
+}
+.product-card:hover .product-actions,
+.product-card:focus-within .product-actions {
+  opacity: 1;
+  transform: translateX(0);
+}
+.action-btn {
+  width: 36px;
+  height: 36px;
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-md);
+  display: grid;
+  place-items: center;
+  color: var(--color-text-muted);
+  font-size: .875rem;
+  transition: background var(--transition), color var(--transition), border-color var(--transition);
+}
+.action-btn:hover,
+.action-btn:focus-visible {
+  background: var(--color-accent);
+  color: #fff;
+  border-color: var(--color-accent);
+}
+.action-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+.product-card-body {
+  padding: 1rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+}
+.product-brand {
+  font-size: .75rem;
+  font-weight: 600;
+  color: var(--color-text-muted);
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  margin-bottom: .25rem;
+}
+.product-name {
+  font-size: .9375rem;
+  font-weight: 600;
+  line-height: 1.3;
+  margin-bottom: .5rem;
+  color: var(--color-text);
+}
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: .375rem;
+  margin-bottom: .625rem;
+}
+.stars {
+  display: flex;
+  gap: 1px;
+  color: #f59e0b;
+  font-size: .8125rem;
+}
+.rating-count {
+  font-size: .75rem;
+  color: var(--color-text-muted);
+}
+.product-pricing {
+  display: flex;
+  align-items: center;
+  gap: .625rem;
+  margin-top: auto;
+  flex-wrap: wrap;
+}
+.price-current {
+  font-size: 1.0625rem;
+  font-weight: 700;
+  color: var(--color-text);
+}
+.price-original {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+.price-discount {
+  font-size: .75rem;
+  font-weight: 700;
+  color: var(--color-accent);
+}
+
+.product-card-footer {
+  padding: .75rem 1rem 1rem;
+  border-top: 1px solid var(--color-border);
+}
+
+.add-to-cart-btn {
+  width: 100%;
+  background: var(--color-brand);
+  color: #fff;
+  padding: .625rem;
+  border-radius: var(--radius-md);
+  font-size: .875rem;
+  font-weight: 600;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  gap: .5rem;
+  transition: background var(--transition), transform var(--transition);
+}
+.add-to-cart-btn:hover {
+  background: var(--color-accent);
+  transform: translateY(-1px);
+}
+.add-to-cart-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 3px;
+}
+
+/* =========================================
+   Sections Spacing
+   ========================================= */
+.section {
+  padding-block: 4rem;
+}
+.section + .section {
+  border-top: 1px solid var(--color-border);
+}
+
+/* =========================================
+   Deals Section
+   ========================================= */
+.deals-section {
+  background: linear-gradient(135deg, #fff5f7 0%, #fff8f0 100%);
+}
+
+.countdown-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 1.5rem;
+}
+
+/* Featured Deal Card (large) */
+.deal-featured {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-xl);
+  overflow: hidden;
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  box-shadow: var(--shadow-md);
+}
+
+.deal-featured-media {
+  background: linear-gradient(135deg, #1a1a2e, #3a1a3a);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 8rem;
+  min-height: 320px;
+}
+
+.deal-featured-body {
+  padding: 2.5rem 2rem;
+  display: flex;
+  flex-direction: column;
+  justify-content: center;
+  gap: 1rem;
+}
+
+.deal-tag {
+  display: inline-flex;
+  align-items: center;
+  gap: .375rem;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: .75rem;
+  font-weight: 700;
+  padding: .3rem .75rem;
+  border-radius: 100px;
+  text-transform: uppercase;
+  letter-spacing: .05em;
+  align-self: flex-start;
+}
+
+.deal-title {
+  font-size: 1.5rem;
+  font-weight: 800;
+  letter-spacing: -.02em;
+  line-height: 1.2;
+}
+
+.deal-description {
+  font-size: .9375rem;
+  color: var(--color-text-muted);
+  line-height: 1.6;
+}
+
+.deal-pricing {
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+}
+.deal-price-current {
+  font-size: 2rem;
+  font-weight: 800;
+  color: var(--color-accent);
+}
+.deal-price-original {
+  font-size: 1rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+.deal-discount-badge {
+  background: rgba(233,69,96,.1);
+  color: var(--color-accent);
+  font-size: .8125rem;
+  font-weight: 700;
+  padding: .25rem .625rem;
+  border-radius: 100px;
+}
+
+.countdown {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+}
+.countdown-label {
+  font-size: .8125rem;
+  color: var(--color-text-muted);
+  font-weight: 500;
+}
+.countdown-timer {
+  display: flex;
+  align-items: center;
+  gap: .25rem;
+}
+.countdown-segment {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  background: var(--color-brand);
+  color: #fff;
+  border-radius: var(--radius-sm);
+  padding: .25rem .5rem;
+  min-width: 38px;
+}
+.countdown-num {
+  font-size: 1.125rem;
+  font-weight: 800;
+  line-height: 1;
+  font-variant-numeric: tabular-nums;
+}
+.countdown-unit {
+  font-size: .5625rem;
+  font-weight: 600;
+  text-transform: uppercase;
+  letter-spacing: .06em;
+  color: rgba(255,255,255,.6);
+}
+.countdown-sep {
+  font-size: 1.125rem;
+  font-weight: 700;
+  color: var(--color-text-muted);
+  margin-bottom: .5rem;
+}
+
+/* Mini Deal Cards */
+.deals-sidebar {
+  display: flex;
+  flex-direction: column;
+  gap: 1.5rem;
+}
+
+.deal-mini-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  padding: 1.25rem;
+  display: grid;
+  grid-template-columns: 80px 1fr;
+  gap: 1rem;
+  align-items: center;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.deal-mini-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-2px);
+}
+
+.deal-mini-media {
+  width: 80px;
+  height: 80px;
+  border-radius: var(--radius-md);
+  background: var(--color-bg);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 2.5rem;
+  flex-shrink: 0;
+  overflow: hidden;
+}
+
+.deal-mini-name {
+  font-size: .9375rem;
+  font-weight: 600;
+  margin-bottom: .375rem;
+  line-height: 1.3;
+}
+.deal-mini-pricing {
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  margin-bottom: .5rem;
+}
+.deal-mini-price {
+  font-size: 1rem;
+  font-weight: 700;
+  color: var(--color-accent);
+}
+.deal-mini-original {
+  font-size: .8125rem;
+  color: var(--color-text-muted);
+  text-decoration: line-through;
+}
+
+.deal-progress {
+  display: flex;
+  flex-direction: column;
+  gap: .25rem;
+}
+.progress-bar {
+  height: 5px;
+  background: var(--color-border);
+  border-radius: 100px;
+  overflow: hidden;
+}
+.progress-fill {
+  height: 100%;
+  background: linear-gradient(90deg, var(--color-accent), var(--color-badge-deal));
+  border-radius: 100px;
+  transition: width 1s ease;
+}
+.progress-label {
+  font-size: .6875rem;
+  color: var(--color-text-muted);
+}
+.progress-label strong { color: var(--color-accent); }
+
+/* =========================================
+   Trust Bar
+   ========================================= */
+.trust-bar {
+  background: var(--color-surface);
+  padding-block: 1.5rem;
+  border-top: 1px solid var(--color-border);
+  border-bottom: 1px solid var(--color-border);
+}
+
+.trust-list {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 1rem;
+  text-align: center;
+}
+
+.trust-item {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: .5rem;
+}
+.trust-icon {
+  font-size: 1.75rem;
+  line-height: 1;
+}
+.trust-title {
+  font-size: .875rem;
+  font-weight: 700;
+}
+.trust-subtitle {
+  font-size: .75rem;
+  color: var(--color-text-muted);
+}
+
+/* =========================================
+   Editorial / Content Section
+   ========================================= */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1fr 1fr 1fr;
+  gap: 1.5rem;
+}
+
+.editorial-card {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: box-shadow var(--transition), transform var(--transition);
+}
+.editorial-card:hover {
+  box-shadow: var(--shadow-md);
+  transform: translateY(-2px);
+}
+
+.editorial-card--featured {
+  grid-column: span 2;
+}
+
+.editorial-media {
+  position: relative;
+  aspect-ratio: 16/9;
+  background: linear-gradient(135deg, #1a1a2e, #3a1a3a);
+  overflow: hidden;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+}
+.editorial-card--featured .editorial-media {
+  aspect-ratio: 16/9;
+}
+
+.editorial-cover-emoji {
+  font-size: 6rem;
+  line-height: 1;
+  opacity: .9;
+}
+
+.editorial-media-overlay {
+  position: absolute;
+  inset: 0;
+  background: linear-gradient(to top, rgba(0,0,0,.6) 0%, transparent 60%);
+}
+
+.editorial-category {
+  display: inline-flex;
+  align-items: center;
+  gap: .375rem;
+  background: var(--color-accent);
+  color: #fff;
+  font-size: .6875rem;
+  font-weight: 700;
+  padding: .25rem .625rem;
+  border-radius: 100px;
+  text-transform: uppercase;
+  letter-spacing: .05em;
+  margin-bottom: .75rem;
+}
+
+.editorial-body {
+  padding: 1.25rem;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+  gap: .5rem;
+}
+
+.editorial-title {
+  font-size: 1.0625rem;
+  font-weight: 700;
+  line-height: 1.3;
+  letter-spacing: -.01em;
+}
+.editorial-card--featured .editorial-title {
+  font-size: 1.25rem;
+}
+
+.editorial-excerpt {
+  font-size: .875rem;
+  color: var(--color-text-muted);
+  line-height: 1.6;
+  flex: 1;
+}
+
+.editorial-meta {
+  display: flex;
+  align-items: center;
+  gap: .75rem;
+  font-size: .75rem;
+  color: var(--color-text-muted);
+  margin-top: .75rem;
+  padding-top: .75rem;
+  border-top: 1px solid var(--color-border);
+}
+.editorial-avatar {
+  width: 28px;
+  height: 28px;
+  border-radius: 50%;
+  background: var(--color-bg);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: .875rem;
+  flex-shrink: 0;
+  border: 1.5px solid var(--color-border);
+}
+.editorial-author { font-weight: 600; color: var(--color-text); }
+.editorial-read-more {
+  margin-left: auto;
+  display: inline-flex;
+  align-items: center;
+  gap: .25rem;
+  font-weight: 600;
+  color: var(--color-accent);
+  font-size: .75rem;
+  transition: gap var(--transition);
+}
+.editorial-read-more:hover,
+.editorial-read-more:focus-visible { gap: .5rem; }
+.editorial-read-more:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+  border-radius: var(--radius-sm);
+}
+
+/* =========================================
+   Newsletter Section
+   ========================================= */
+.newsletter-section {
+  background: var(--color-brand);
+  color: #fff;
+}
+
+.newsletter-inner {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 3rem;
+  align-items: center;
+  padding-block: 4rem;
+}
+
+.newsletter-eyebrow {
+  font-size: .75rem;
+  font-weight: 700;
+  letter-spacing: .1em;
+  text-transform: uppercase;
+  color: var(--color-accent);
+  margin-bottom: .75rem;
+}
+.newsletter-title {
+  font-size: clamp(1.5rem, 3vw, 2.25rem);
+  font-weight: 800;
+  letter-spacing: -.02em;
+  line-height: 1.15;
+  margin-bottom: 1rem;
+}
+.newsletter-description {
+  color: rgba(255,255,255,.7);
+  font-size: .9375rem;
+  line-height: 1.7;
+}
+
+.newsletter-form-wrapper {
+  display: flex;
+  flex-direction: column;
+  gap: 1rem;
+}
+
+.newsletter-form {
+  display: flex;
+  gap: .75rem;
+  flex-wrap: wrap;
+}
+.newsletter-input {
+  flex: 1;
+  min-width: 200px;
+  background: rgba(255,255,255,.1);
+  border: 1.5px solid rgba(255,255,255,.2);
+  border-radius: var(--radius-md);
+  padding: .75rem 1rem;
+  color: #fff;
+  font-size: .9375rem;
+  font-family: inherit;
+  transition: border-color var(--transition), box-shadow var(--transition);
+}
+.newsletter-input::placeholder { color: rgba(255,255,255,.45); }
+.newsletter-input:focus {
+  outline: none;
+  border-color: var(--color-accent);
+  box-shadow: 0 0 0 3px rgba(233,69,96,.25);
+}
+
+.newsletter-perks {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 1rem;
+}
+.perk {
+  display: flex;
+  align-items: center;
+  gap: .375rem;
+  font-size: .8125rem;
+  color: rgba(255,255,255,.65);
+}
+.perk-icon { color: var(--color-accent); font-size: 1rem; }
+
+/* =========================================
+   Footer
+   ========================================= */
+.site-footer {
+  background: #111122;
+  color: rgba(255,255,255,.75);
+  padding-top: 4rem;
+}
+
+.footer-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr 1fr;
+  gap: 3rem;
+  padding-bottom: 3rem;
+  border-bottom: 1px solid rgba(255,255,255,.08);
+}
+
+.footer-brand-name {
+  font-size: 1.25rem;
+  font-weight: 800;
+  color: #fff;
+  letter-spacing: -.04em;
+  display: flex;
+  align-items: center;
+  gap: .5rem;
+  margin-bottom: 1rem;
+}
+
+.footer-tagline {
+  font-size: .875rem;
+  line-height: 1.7;
+  max-width: 32ch;
+  margin-bottom: 1.5rem;
+  color: rgba(255,255,255,.55);
+}
+
+.social-links {
+  display: flex;
+  gap: .5rem;
+}
+.social-btn {
+  width: 36px;
+  height: 36px;
+  background: rgba(255,255,255,.08);
+  border-radius: var(--radius-md);
+  display: grid;
+  place-items: center;
+  color: rgba(255,255,255,.65);
+  font-size: .875rem;
+  transition: background var(--transition), color var(--transition);
+}
+.social-btn:hover {
+  background: var(--color-accent);
+  color: #fff;
+}
+.social-btn:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+.footer-nav-title {
+  font-size: .8125rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: .08em;
+  color: rgba(255,255,255,.4);
+  margin-bottom: 1.25rem;
+}
+
+.footer-nav-list {
+  display: flex;
+  flex-direction: column;
+  gap: .75rem;
+}
+
+.footer-nav-link {
+  font-size: .875rem;
+  color: rgba(255,255,255,.65);
+  transition: color var(--transition);
+}
+.footer-nav-link:hover {
+  color: #fff;
+}
+.footer-nav-link:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+  border-radius: var(--radius-sm);
+  color: #fff;
+}
+
+.footer-bottom {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 1rem;
+  padding-block: 1.5rem;
+  font-size: .8125rem;
+  color: rgba(255,255,255,.35);
+  flex-wrap: wrap;
+}
+
+.footer-legal {
+  display: flex;
+  gap: 1.25rem;
+  flex-wrap: wrap;
+}
+.footer-legal a {
+  color: rgba(255,255,255,.35);
+  transition: color var(--transition);
+}
+.footer-legal a:hover { color: rgba(255,255,255,.7); }
+.footer-legal a:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+  border-radius: var(--radius-sm);
+}
+
+/* =========================================
+   Cart Drawer
+   ========================================= */
+.cart-overlay {
+  position: fixed;
+  inset: 0;
+  background: rgba(0,0,0,.5);
+  z-index: 200;
+  opacity: 0;
+  visibility: hidden;
+  transition: opacity var(--transition), visibility var(--transition);
+  backdrop-filter: blur(4px);
+}
+.cart-overlay.open {
+  opacity: 1;
+  visibility: visible;
+}
+
+.cart-drawer {
+  position: fixed;
+  top: 0;
+  right: 0;
+  bottom: 0;
+  width: min(400px, 100vw);
+  background: var(--color-surface);
+  z-index: 201;
+  transform: translateX(100%);
+  transition: transform 300ms cubic-bezier(.4,0,.2,1);
+  display: flex;
+  flex-direction: column;
+  box-shadow: -8px 0 32px rgba(0,0,0,.15);
+}
+.cart-drawer.open {
+  transform: translateX(0);
+}
+
+.cart-header {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  padding: 1.25rem 1.5rem;
+  border-bottom: 1px solid var(--color-border);
+}
+.cart-title {
+  font-size: 1.125rem;
+  font-weight: 700;
+}
+.cart-close {
+  width: 36px;
+  height: 36px;
+  border-radius: var(--radius-md);
+  display: grid;
+  place-items: center;
+  color: var(--color-text-muted);
+  font-size: 1.25rem;
+  transition: background var(--transition), color var(--transition);
+}
+.cart-close:hover {
+  background: var(--color-bg);
+  color: var(--color-text);
+}
+.cart-close:focus-visible {
+  outline: 2px solid var(--color-accent);
+  outline-offset: 2px;
+}
+
+.cart-body {
+  flex: 1;
+  overflow-y: auto;
+  padding: 1.25rem 1.5rem;
+  display: flex;
+  flex-direction: column;
+  gap: 1rem;
+}
+
+.cart-empty {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 1rem;
+  padding-block: 3rem;
+  color: var(--color-text-muted);
+  text-align: center;
+}
+.cart-empty-icon { font-size: 3.5rem; }
+.cart-empty-text { font-weight: 600; }
+
+.cart-item {
+  display: grid;
+  grid-template-columns: 64px 1fr auto;
+  gap: .875rem;
+  align-items: start;
+}
+.cart-item-img {
+  width: 64px;
+  height: 64px;
+  border-radius: var(--radius-md);
