+  {
+    id: 103,
+    name: 'Cashmere Scarf',
+    emoji: '🧣',
+    price: 65,
+    original: 110,
+    sold: 55,
+    total: 75,
+  },
+];
+
+// ── State ─────────────────────────────────────────
+
+const state = {
+  cart: [],
+  wishlist: new Set(),
+  activeCategory: 'all',
+  cartOpen: false,
+};
+
+// ── Helpers ───────────────────────────────────────
+
+function discount(price, original) {
+  if (!original) return null;
+  return Math.round(((original - price) / original) * 100);
+}
+
+function stars(rating) {
+  const full  = Math.floor(rating);
+  const half  = rating % 1 >= 0.5 ? 1 : 0;
+  const empty = 5 - full - half;
+  return '★'.repeat(full) + (half ? '½' : '') + '☆'.repeat(empty);
+}
+
+function fmt(n) {
+  return '$' + n.toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
+}
+
+function badgeHTML(badge) {
+  const map = { new: 'badge-new', sale: 'badge-sale', hot: 'badge-hot' };
+  const labels = { new: 'New', sale: 'Sale', hot: '🔥 Hot' };
+  return `<span class="badge ${map[badge]}">${labels[badge]}</span>`;
+}
+
+// ── Cart ──────────────────────────────────────────
+
+function cartTotal() {
+  return state.cart.reduce((sum, item) => sum + item.price * item.qty, 0);
+}
+
+function cartItemCount() {
+  return state.cart.reduce((sum, item) => sum + item.qty, 0);
+}
+
+function addToCart(productId) {
+  const product = PRODUCTS.find(p => p.id === productId);
+  if (!product) return;
+
+  const existing = state.cart.find(i => i.id === productId);
+  if (existing) {
+    existing.qty++;
+  } else {
+    state.cart.push({ ...product, qty: 1 });
+  }
+
+  updateCartUI();
+  showToast(`✓ ${product.name} added to cart`);
+}
+
+function removeFromCart(productId) {
+  state.cart = state.cart.filter(i => i.id !== productId);
+  updateCartUI();
+}
+
+function changeQty(productId, delta) {
+  const item = state.cart.find(i => i.id === productId);
+  if (!item) return;
+  item.qty = Math.max(1, item.qty + delta);
+  updateCartUI();
+}
+
+function updateCartUI() {
+  // Badge on icon
+  const count = cartItemCount();
+  document.querySelectorAll('.cart-count').forEach(el => {
+    el.textContent = count;
+    el.hidden = count === 0;
+  });
+
+  // Render cart body
+  const body = document.getElementById('cart-body');
+  if (!body) return;
+
+  if (state.cart.length === 0) {
+    body.innerHTML = `
+      <div class="cart-empty" role="status">
+        <span class="cart-empty-icon" aria-hidden="true">🛍️</span>
+        <p class="cart-empty-text">Your cart is empty</p>
+        <p>Add some items to get started!</p>
+      </div>`;
+  } else {
+    body.innerHTML = state.cart.map(item => `
+      <article class="cart-item" aria-label="${item.name}">
+        <div class="cart-item-img" aria-hidden="true">${item.emoji}</div>
+        <div>
+          <p class="cart-item-name">${item.name}</p>
+          <p class="cart-item-variant">${item.variant}</p>
+          <div class="cart-item-qty">
+            <button class="qty-btn" aria-label="Decrease quantity of ${item.name}"
+                    onclick="changeQty(${item.id}, -1)">−</button>
+            <span class="qty-val" aria-live="polite">${item.qty}</span>
+            <button class="qty-btn" aria-label="Increase quantity of ${item.name}"
+                    onclick="changeQty(${item.id}, 1)">+</button>
+          </div>
+        </div>
+        <div style="text-align:right">
+          <p class="cart-item-price">${fmt(item.price * item.qty)}</p>
+          <button class="cart-item-remove" onclick="removeFromCart(${item.id})"
+                  aria-label="Remove ${item.name} from cart">Remove</button>
+        </div>
+      </article>`).join('');
+  }
+
+  // Footer
+  const footer = document.getElementById('cart-footer');
+  if (!footer) return;
+  footer.innerHTML = state.cart.length === 0 ? '' : `
+    <div class="cart-subtotal">
+      <span class="cart-subtotal-label">Subtotal</span>
+      <span class="cart-subtotal-value" aria-live="polite">${fmt(cartTotal())}</span>
+    </div>
+    <p class="cart-shipping-note"><strong>Free shipping</strong> on orders over $75</p>
+    <button class="btn btn-primary" style="width:100%;justify-content:center"
+            onclick="showToast('Checkout coming soon! 🚀')">
+      Proceed to Checkout
+    </button>
+    <button class="btn btn-outline" style="width:100%;justify-content:center"
+            onclick="closeCart()">
+      Continue Shopping
+    </button>`;
+}
+
+function openCart() {
+  state.cartOpen = true;
+  const overlay = document.getElementById('cart-overlay');
+  const drawer  = document.getElementById('cart-drawer');
+  overlay.classList.add('open');
+  drawer.classList.add('open');
+  overlay.removeAttribute('hidden');
+  drawer.removeAttribute('aria-hidden');
+  document.body.style.overflow = 'hidden';
+  setTimeout(() => document.getElementById('cart-close')?.focus(), 50);
+}
+
+function closeCart() {
+  state.cartOpen = false;
+  const overlay = document.getElementById('cart-overlay');
+  const drawer  = document.getElementById('cart-drawer');
+  overlay.classList.remove('open');
+  drawer.classList.remove('open');
+  overlay.setAttribute('hidden', '');
+  drawer.setAttribute('aria-hidden', 'true');
+  document.body.style.overflow = '';
+  document.querySelector('[aria-label="Open shopping cart"]')?.focus();
+}
+
+// ── Wishlist ──────────────────────────────────────
+
+function toggleWishlist(productId) {
+  if (state.wishlist.has(productId)) {
+    state.wishlist.delete(productId);
+    showToast('💔 Removed from wishlist');
+  } else {
+    state.wishlist.add(productId);
+    showToast('❤️ Added to wishlist');
+  }
+  updateWishlistUI();
+}
+
+function updateWishlistUI() {
+  document.querySelectorAll('[data-wishlist-id]').forEach(btn => {
+    const id = parseInt(btn.dataset.wishlistId, 10);
+    const active = state.wishlist.has(id);
+    btn.setAttribute('aria-pressed', active);
+    btn.setAttribute('aria-label', active ? 'Remove from wishlist' : 'Add to wishlist');
+    btn.querySelector('.wish-icon').textContent = active ? '❤️' : '🤍';
+  });
+}
+
+// ── Category Filter ───────────────────────────────
+
+function filterCategory(cat) {
+  state.activeCategory = cat;
+  document.querySelectorAll('.category-chip').forEach(chip => {
+    const active = chip.dataset.cat === cat;
+    chip.setAttribute('aria-pressed', active);
+  });
+  renderProducts();
+}
+
+// ── Toast ─────────────────────────────────────────
+
+function showToast(message) {
+  const container = document.getElementById('toast-container');
+  if (!container) return;
+
+  const toast = document.createElement('div');
+  toast.className = 'toast';
+  toast.setAttribute('role', 'status');
+  toast.setAttribute('aria-live', 'polite');
+  toast.innerHTML = `<span class="toast-icon" aria-hidden="true">✓</span>${message}`;
+  container.appendChild(toast);
+
+  setTimeout(() => {
+    toast.classList.add('leaving');
+    toast.addEventListener('animationend', () => toast.remove());
+  }, 2800);
+}
+
+// ── Countdown Timer ───────────────────────────────
+
+function startCountdown() {
+  const end = new Date();
+  end.setHours(end.getHours() + 5, end.getMinutes() + 47, end.getSeconds() + 23, 0);
+
+  function tick() {
+    const now  = new Date();
+    const diff = Math.max(0, end - now);
+
+    const h = String(Math.floor(diff / 3600000)).padStart(2, '0');
+    const m = String(Math.floor((diff % 3600000) / 60000)).padStart(2, '0');
+    const s = String(Math.floor((diff % 60000) / 1000)).padStart(2, '0');
+
+    const hEl = document.getElementById('cd-h');
+    const mEl = document.getElementById('cd-m');
+    const sEl = document.getElementById('cd-s');
+    if (hEl) hEl.textContent = h;
+    if (mEl) mEl.textContent = m;
+    if (sEl) sEl.textContent = s;
+  }
+
+  tick();
+  setInterval(tick, 1000);
+}
+
+// ── Render: Product Grid ──────────────────────────
+
+function productCardHTML(product) {
+  const disc = discount(product.price, product.original);
+  const wished = state.wishlist.has(product.id);
+
+  return `
+    <article class="product-card" aria-label="${product.name} by ${product.brand}">
+      <div class="product-card-media">
+        <div class="product-img" aria-hidden="true" role="img">${product.emoji}</div>
+        ${product.badges.length ? `
+          <div class="product-badges" aria-label="Product labels">
+            ${product.badges.map(badgeHTML).join('')}
+          </div>` : ''}
+        <div class="product-actions" role="group" aria-label="Quick actions">
+          <button class="action-btn" data-wishlist-id="${product.id}"
+                  aria-pressed="${wished}"
+                  aria-label="${wished ? 'Remove from wishlist' : 'Add to wishlist'}"
+                  onclick="toggleWishlist(${product.id})">
+            <span class="wish-icon" aria-hidden="true">${wished ? '❤️' : '🤍'}</span>
+          </button>
+          <button class="action-btn" aria-label="Quick view ${product.name}"
+                  onclick="showToast('Quick view coming soon!')">
+            <span aria-hidden="true">👁️</span>
+          </button>
+        </div>
+      </div>
+      <div class="product-card-body">
+        <p class="product-brand">${product.brand}</p>
+        <h3 class="product-name">
+          <a href="#" onclick="return false;" aria-label="${product.name} — view product details">
+            ${product.name}
+          </a>
+        </h3>
+        <div class="product-rating" aria-label="Rating: ${product.rating} out of 5, ${product.reviews} reviews">
+          <span class="stars" aria-hidden="true">${stars(product.rating)}</span>
+          <span class="rating-count">(${product.reviews})</span>
+        </div>
+        <div class="product-pricing">
+          <span class="price-current">${fmt(product.price)}</span>
+          ${product.original ? `<span class="price-original">${fmt(product.original)}</span>` : ''}
+          ${disc ? `<span class="price-discount">−${disc}%</span>` : ''}
+        </div>
+      </div>
+      <div class="product-card-footer">
+        <button class="add-to-cart-btn" onclick="addToCart(${product.id})"
+                aria-label="Add ${product.name} to cart — ${fmt(product.price)}">
+          <span aria-hidden="true">🛒</span> Add to Cart
+        </button>
+      </div>
+    </article>`;
+}
+
+function renderProducts() {
+  const grid = document.getElementById('product-grid');
+  if (!grid) return;
+
+  const filtered = state.activeCategory === 'all'
+    ? PRODUCTS
+    : PRODUCTS.filter(p => p.category === state.activeCategory);
+
+  grid.innerHTML = filtered.map(productCardHTML).join('');
+  updateWishlistUI();
+}
+
+// ── Render: Editorial ─────────────────────────────
+
+function editorialCardHTML(article) {
+  return `
+    <article class="editorial-card ${article.featured ? 'editorial-card--featured' : ''}"
+             aria-label="${article.category}: ${article.title}">
+      <div class="editorial-media" aria-hidden="true">
+        <span class="editorial-cover-emoji">${article.coverEmoji}</span>
+        <div class="editorial-media-overlay"></div>
+      </div>
+      <div class="editorial-body">
+        <span class="editorial-category" aria-label="Category">${article.category}</span>
+        <h3 class="editorial-title">${article.title}</h3>
+        <p class="editorial-excerpt">${article.excerpt}</p>
+        <div class="editorial-meta">
+          <div class="editorial-avatar" aria-hidden="true">${article.authorEmoji}</div>
+          <span class="editorial-author">${article.author}</span>
+          <span aria-hidden="true">·</span>
+          <span>${article.readTime}</span>
+          <a href="#" onclick="return false;" class="editorial-read-more"
+             aria-label="Read article: ${article.title}">
+            Read <span aria-hidden="true">→</span>
+          </a>
+        </div>
+      </div>
+    </article>`;
+}
+
+function renderEditorial() {
+  const grid = document.getElementById('editorial-grid');
+  if (!grid) return;
+  grid.innerHTML = EDITORIAL.map(editorialCardHTML).join('');
+}
+
+// ── Render: Mini Deals ────────────────────────────
+
+function miniDealHTML(deal) {
+  const pct   = Math.round((deal.sold / deal.total) * 100);
+  const left  = deal.total - deal.sold;
+  const disc  = discount(deal.price, deal.original);
+
+  return `
+    <article class="deal-mini-card" aria-label="${deal.name} deal">
+      <div class="deal-mini-media" aria-hidden="true">${deal.emoji}</div>
+      <div>
+        <p class="deal-mini-name">${deal.name}</p>
+        <div class="deal-mini-pricing">
+          <span class="deal-mini-price">${fmt(deal.price)}</span>
+          <span class="deal-mini-original">${fmt(deal.original)}</span>
+          ${disc ? `<span class="badge badge-sale" style="font-size:.625rem">${disc}% off</span>` : ''}
+        </div>
+        <div class="deal-progress">
+          <div class="progress-bar" role="progressbar"
+               aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"
+               aria-label="${pct}% sold">
+            <div class="progress-fill" style="width:${pct}%"></div>
+          </div>
+          <p class="progress-label">
+            <strong>${left} left</strong> · ${pct}% sold
+          </p>
+        </div>
+        <button class="btn btn-sm btn-primary" style="margin-top:.5rem"
+                onclick="addToCart(${deal.id < 100 ? deal.id : 1})"
+                aria-label="Add ${deal.name} to cart for ${fmt(deal.price)}">
+          Add to Cart
+        </button>
+      </div>
+    </article>`;
+}
+
+function renderMiniDeals() {
+  const container = document.getElementById('deals-sidebar');
+  if (!container) return;
+  container.innerHTML = MINI_DEALS.map(miniDealHTML).join('');
+}
+
+// ── Mobile Menu ───────────────────────────────────
+
+function toggleMobileMenu() {
+  const nav = document.getElementById('primary-nav');
+  if (!nav) return;
+  const expanded = nav.hidden === false;
+  nav.hidden = expanded;
+  document.getElementById('menu-toggle')
+    ?.setAttribute('aria-expanded', !expanded);
+}
+
+// ── Newsletter ────────────────────────────────────
+
+function handleNewsletter(e) {
+  e.preventDefault();
+  const input = document.getElementById('newsletter-email');
+  if (!input?.value) return;
+  showToast(`🎉 Thanks! Check your inbox at ${input.value}`);
+  input.value = '';
+}
+
+// ── Search ────────────────────────────────────────
+
+function handleSearch(e) {
+  e.preventDefault();
+  const q = document.getElementById('search-input')?.value?.trim();
+  if (q) showToast(`🔍 Showing results for "${q}"`);
+}
+
+// ── Keyboard Trap (Cart Drawer) ───────────────────
+
+document.addEventListener('keydown', e => {
+  if (e.key === 'Escape' && state.cartOpen) closeCart();
+
+  if (state.cartOpen && e.key === 'Tab') {
+    const drawer = document.getElementById('cart-drawer');
+    const focusable = drawer.querySelectorAll(
+      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
+    );
+    const first = focusable[0];
+    const last  = focusable[focusable.length - 1];
+    if (e.shiftKey && document.activeElement === first) {
+      e.preventDefault();
+      last.focus();
+    } else if (!e.shiftKey && document.activeElement === last) {
+      e.preventDefault();
+      first.focus();
+    }
+  }
+});
+
+// ── Init ──────────────────────────────────────────
+
+document.addEventListener('DOMContentLoaded', () => {
+  renderProducts();
+  renderEditorial();
+  renderMiniDeals();
+  startCountdown();
+  updateCartUI();
+
+  // Cart overlay click-outside
+  document.getElementById('cart-overlay')?.addEventListener('click', closeCart);
+
+  // Newsletter form
+  document.getElementById('newsletter-form')?.addEventListener('submit', handleNewsletter);
+
+  // Search form
+  document.getElementById('search-form')?.addEventListener('submit', handleSearch);
+
+  // Lazy-load simulation: stagger product cards
+  const observer = new IntersectionObserver((entries) => {
+    entries.forEach(entry => {
+      if (entry.isIntersecting) {
+        entry.target.style.opacity = '1';
+        entry.target.style.transform = 'translateY(0)';
+        observer.unobserve(entry.target);
+      }
+    });
+  }, { threshold: 0.1 });
+
+  document.querySelectorAll('.product-card, .editorial-card, .deal-mini-card').forEach(card => {
+    card.style.opacity = '0';
+    card.style.transform = 'translateY(16px)';
+    card.style.transition = 'opacity 400ms ease, transform 400ms ease, box-shadow 200ms ease';
+    observer.observe(card);
+  });
+});
+
')

